/**
 * Creating a sidebar enables you to:
 - create an ordered group of docs
 - render a sidebar for each doc of that group
 - provide next/previous navigation

 The sidebars can be generated from the filesystem, or explicitly defined here.

 Create as many sidebars as you want.
 */

// @ts-check

/** @type {import('@docusaurus/plugin-content-docs').SidebarsConfig} */
const sidebars = {
  // By default, Docusaurus generates a sidebar from the docs folder structure
  // tutorialSidebar: [{type: 'autogenerated', dirName: '.'}],

  // But you can create a sidebar manually
  mySidebar: [
    {
      type: 'doc',
      id: 'introduction', // assuming introduction.md
    },
    {
      type: 'doc',
      id: 'getting-started', // assuming getting-started.md
    },
    {
      type: 'category',
      label: 'API Reference',
      items: ['api/api-overview'], // placeholder, e.g., docs/api/api-overview.md
    },
    {
      type: 'category',
      label: 'Frontend',
      items: ['frontend/frontend-overview'], // placeholder
    },
    {
      type: 'category',
      label: 'Backend',
      items: ['backend/backend-overview'], // placeholder
    },
    {
      type: 'category',
      label: 'Deployment',
      items: ['deployment/deployment-overview'], // placeholder
    },
    {
      type: 'category',
      label: 'Development',
      items: ['development/development-overview'], // placeholder
    },
  ],
};

module.exports = sidebars;
